import{_ as e,o as t,c as a,a4 as i}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"翻翻类比","description":"","frontmatter":{"date":"2026-08-24T21:07:51","title":"翻翻类比","categories":["AI","定投","类比"],"tags":["AI","定投","类比"]},"headers":[{"level":2,"title":"为什么还做这件事","slug":"为什么还做这件事","link":"#为什么还做这件事","children":[]},{"level":2,"title":"从「宝库」到「翻翻」","slug":"从「宝库」到「翻翻」","link":"#从「宝库」到「翻翻」","children":[]},{"level":2,"title":"翻起来什么样","slug":"翻起来什么样","link":"#翻起来什么样","children":[]},{"level":2,"title":"还是那个场景","slug":"还是那个场景","link":"#还是那个场景","children":[]},{"level":2,"title":"一些说明，也是求助","slug":"一些说明-也是求助","link":"#一些说明-也是求助","children":[]}],"relativePath":"posts/course100/061.md","filePath":"posts/course100/061.md"}'),o={name:"posts/course100/061.md"};function r(s,l,n,p,c,d){return t(),a("div",null,[...l[0]||(l[0]=[i('<blockquote><p>类比，是从已知通往未知的桥梁。</p></blockquote><p>四年多前，我做过一款小程序「类比宝库」—— 一个用来收集类比的本子。</p><p>四年多后，我把它重做了一版，改名为「翻翻类比」。</p><h2 id="为什么还做这件事" tabindex="-1">为什么还做这件事 <a class="header-anchor" href="#为什么还做这件事" aria-label="Permalink to &quot;为什么还做这件事&quot;">​</a></h2><p>上帝说要有光，于是便有了光。笑来老师说，每个精彩的类比都是一笔财富，于是便有了这个小程序。</p><p>当年设计 Logo <code>&gt;≈&lt;</code> 时的想法：类比是约等于，不是等于号 —— 用得恰当，它就是大于号；用得不恰当，它就是小于号。</p><p>如果参加过笑来老师的写作课，应该知道第五课有个作业 —— 准备一个本子，从今天开始，遇到任何类比都收集起来。</p><p>最新的 AI 课程里，他又用了一个类比：Git 是平行时光机。你看，好类比永远管用。</p><p>「翻翻类比」，就是这个本子。</p><h2 id="从「宝库」到「翻翻」" tabindex="-1">从「宝库」到「翻翻」 <a class="header-anchor" href="#从「宝库」到「翻翻」" aria-label="Permalink to &quot;从「宝库」到「翻翻」&quot;">​</a></h2><p>「类比宝库」走的是众人拾柴的路线 —— 大家一起攒。后来停更了，很现实的原因：微信的认证费和云服务开销，对一个个人小程序来说，扛不动。</p><p>这中间，我用墨问小程序更新、收集过一段时间的类比，但拿它收集和分享类比，总觉得隔了一层纱，不够直接。后来想明白了，我自己的需求其实很简单：收集类比，是为了有一天能用上 —— 随时翻到，翻得顺手，翻得舒服。</p><p>所以这次，思路被成本逼出来了：与其做一个「在线宝库」，不如先做一个「离线卡片集」。</p><ul><li>类比库随小程序一起发布、随版本更新。如今一共 <strong>185 句</strong>：其中一部分从当年历史数据库里迁出来的 —— 众人拾过的柴，还在这座炉子里烧着；剩下的，是我陆陆续续攒的。</li><li>无网络、无登录、无云开发，不采任何信息。运维成本？题目直接删掉了。</li></ul><h2 id="翻起来什么样" tabindex="-1">翻起来什么样 <a class="header-anchor" href="#翻起来什么样" aria-label="Permalink to &quot;翻起来什么样&quot;">​</a></h2><blockquote><p>指尖轻舞，流光溢彩。「翻翻类比」邀您步入一场全屏的思维漫游。左右滑动，在绚烂渐变中拾取智慧的隐喻；长按定格，将瞬间的顿悟化作海报珍藏。类比，是已知通往未知的桥梁 —— 一句妙语，洞见更广阔的世界。</p></blockquote><p>一句话概括：全屏，左滑，无尽头。打开就是一句类比，居中衬在渐变色板上。左滑下一句，右滑上一句，卡片跟着手指回弹，翻页轻轻一震。</p><p>几点设计：</p><ul><li><strong>20 套渐变色板</strong>：深蓝、米白、荧光绿……相邻两张不重样，翻起来像一叠老明信片。</li><li><strong>一屏一句</strong>：字号自适应，短句舒展，长句也容得下。</li><li><strong>长按生成海报</strong>：当前句子和配色渲染成一张卡片，右下角带小程序码，可存可分享。</li><li><strong>搜索</strong>：多关键词过滤，命中高亮，找到后直接进入卡片模式，不影响首页进度。</li></ul><p>看不见的讲究：</p><ul><li><strong>洗牌队列</strong>：不是随机抽一句，而是用 Fisher-Yates 把整个类比库洗成一轮 —— 一轮之内句句不重、句句都会出现，翻完自动重洗，衔接处还做了去重。</li><li><strong>记住进度</strong>：退出再进，从上次翻到的地方接着翻。</li></ul><h2 id="还是那个场景" tabindex="-1">还是那个场景 <a class="header-anchor" href="#还是那个场景" aria-label="Permalink to &quot;还是那个场景&quot;">​</a></h2><p>等车时，排队时，想刷点什么的时候 —— 打开它。</p><p>现在刷的是短视频同款手势。刷十条短视频，笑完就忘了；翻十句类比，总有一句会留下来，变成你的财富。</p><h2 id="一些说明-也是求助" tabindex="-1">一些说明，也是求助 <a class="header-anchor" href="#一些说明-也是求助" aria-label="Permalink to &quot;一些说明，也是求助&quot;">​</a></h2><ul><li>类比库随小程序发版更新。想分享的，直接发我微信（Crazy_Airhead），精选后收录。至于怎么让大家不经我手就能往里添柴 —— 还在想，有好点子随时喊我。</li><li>小程序预留了广告位，目前没有开启；开了的话，多包涵。</li><li>四年前，自己主要做后端开发，小程序开发是个新手。四年后有了 AI 的帮助，这个新手做出来的小程序，交互体验好了不少 —— 当然肯定还有不尽如人意的地方，请继续多多包涵，继续提建议。</li></ul><p>微信里搜「翻翻类比」，翻翻看。</p>',27)])])}const g=e(o,[["render",r]]);export{h as __pageData,g as default};
